"""PreToolUse(Edit|Write): refuse edits to generated files (root index.html, dist/).

Both are regenerated from engine/ui/landing.html by `spectra serve` / `spectra build`.
Exit 2 = block; the stderr message goes back to Claude.
"""

import json
import os
import sys

data = json.load(sys.stdin)
path = data.get("tool_input", {}).get("file_path", "")
root = os.path.realpath(os.environ.get("CLAUDE_PROJECT_DIR", data.get("cwd", ".")))
rel = os.path.relpath(os.path.realpath(path), root) if path else ""

if rel == "index.html" or rel == "dist" or rel.startswith("dist" + os.sep):
    print(
        f"{rel} is generated by `uv run spectra serve|build` from engine/ui/landing.html "
        "(and the scenarios). Edit the template / sources instead.",
        file=sys.stderr,
    )
    sys.exit(2)
